"""Editable Metadata Miner starter generated by `fomo provision`.

Participants edit the classifier (categories, instructions, thresholds); the Azure plumbing
(Blob listing, extraction, decision API, metadata merge, hosted deployment) is shared code.
The reference answer stays in `decision/reference_classifier.yaml` and is used by cheatcode.
"""

from __future__ import annotations

from pathlib import Path

import yaml

from ..decision.config import REFERENCE_CONFIG
from ..naming import ParticipantNames

TODO_CRITERIA = {
    "contract": "TODO: describe what makes a document an actual binding agreement. Hint: think about "
                "parties, obligations, term and signatures - not how often the word 'contract' appears.",
    "presentation": "TODO: describe slide decks. Hint: one trap in the corpus is a training deck ABOUT "
                    "contract management that repeats payment-terms language.",
}

TRY_SCRIPT = '''"""Try your classifier on a few local corpus files. Read-only: calls Microsoft-Decision-1,
prints per-option probabilities, writes nothing to Blob storage.

    uv run python {path} doc-003 doc-018
"""

import sys
from pathlib import Path

from fomo.config import Environment
from fomo.data.corpus import CORPUS_DIR, load_manifest
from fomo.data.extract import extract
from fomo.decision.client import DecisionClient, build_state
from fomo.decision.config import load_classifier_config
from fomo.decision.policy import apply_policy
from fomo.errors import ConfigError

HERE = Path(__file__).resolve().parent
try:
    cfg = load_classifier_config(HERE / "classifier.yaml")
except ConfigError as exc:
    sys.exit(f"{{exc}}\\nfix: {{exc.fix}}")
env = Environment.load().require()
client = DecisionClient(env.resolved_decision_endpoint(), env.decision_deployment)
_, docs = load_manifest()
wanted = set(sys.argv[1:]) or {{"doc-003", "doc-018"}}
for doc in docs:
    if doc.doc_id not in wanted:
        continue
    ex = extract(doc.blob_name, doc.path(CORPUS_DIR).read_bytes())
    result = client.classify(build_state(ex.text, cfg, title=ex.title, fmt=ex.fmt), cfg)
    outcome = apply_policy(result, cfg)
    top = sorted(result.probabilities.items(), key=lambda kv: -kv[1])[:3]
    print(f"{{doc.doc_id}}  {{outcome.label:<16}} ({{outcome.reason}})  "
          + "  ".join(f"{{k}}={{v:.2f}}" for k, v in top) + f"  {{result.latency_ms}}ms")
'''

README = """# Your Metadata Miner ({hackername})

You own the *classifier*; the workshop code owns the Azure plumbing.

| File | What to do |
| --- | --- |
| `classifier.yaml` | Finish the TODO category descriptions, tune `instructions` and `thresholds`, bump `version` |
| `try_classifier.py` | Read-only experiment: `uv run python {run_dir}/miner/try_classifier.py doc-003 doc-018` |

Loop:

1. Edit `classifier.yaml` (the loader rejects remaining `TODO`s).
2. Try a few documents: `uv run python {run_dir}/miner/try_classifier.py doc-003 doc-007 doc-018`.
3. Deploy and run YOUR classifier as the hosted Foundry agent `{agent}`:
   `uv run fomo miner deploy --classifier {run_dir}/miner/classifier.yaml --apply`
   then `uv run fomo miner run --hosted --apply` (add `--only doc-003 --dry-run` for a single test).
4. Index the new metadata and build Smart RAG: `uv run fomo smart --apply`.
5. Compare: `uv run fomo eval`.

Questions worth answering: which documents land in `needs_review` and why? What happens to
recall when you raise `min_probability`? Does the contract-management deck still look like a contract?

Stuck? `uv run fomo cheatcode --apply` deploys the reference classifier end to end.
"""


def write_starter(names: ParticipantNames, *, force: bool = False) -> tuple[Path, bool]:
    """Returns (directory, classifier_created). Never overwrites participant edits unless force;
    missing helper files (try script, README) are restored individually."""
    folder = Path(names.run_dir) / "miner"
    target = folder / "classifier.yaml"
    folder.mkdir(parents=True, exist_ok=True)
    created = False
    if force or not target.exists():
        data = yaml.safe_load(REFERENCE_CONFIG.read_text(encoding="utf-8"))
        data["version"] = f"{names.hackername}-v1"
        for label, todo in TODO_CRITERIA.items():
            data["criteria"][label] = todo
        header = ("# Your classifier. Finish the TODOs, bump `version` on every change, then deploy with\n"
                  "#   uv run fomo miner deploy --classifier <this file> --apply\n"
                  "# Microsoft-Decision-1 chooses ONE criteria key and returns per-option probabilities.\n")
        target.write_text(header + yaml.safe_dump(data, sort_keys=False, width=100, allow_unicode=False),
                          encoding="utf-8")
        created = True
    helpers = {
        "try_classifier.py": TRY_SCRIPT.format(path=f"{names.run_dir}/miner/try_classifier.py"),
        "README.md": README.format(hackername=names.hackername, run_dir=names.run_dir,
                                   agent=names.metadata_miner_agent),
    }
    for name, text in helpers.items():
        path = folder / name
        if force or not path.exists():
            path.write_text(text, encoding="utf-8")
    return folder, created
